import { useEffect, useState } from "react";
import { api } from "../api/manuscriptApi"; // axios instance
import axios from "axios";
import { useParams, useNavigate } from "react-router-dom";

export default function ManuscriptForm({ method }) {
  const { id } = useParams();
  const navigate = useNavigate();

  const token = localStorage.getItem("token");

  const [authors, setAuthors] = useState([]);
  const [loading, setLoading] = useState(true);

  const [form, setForm] = useState({
    title: "",
    abstract: "",
    keywords: "",
    reference_list: "",
    cover_letter: "",
    manuscript_file: null,
    supplementary_materials: [],
    plagiarism_score: 0,
    author_id: "",
    journal_id: "",
    assigned_editor_id: "",
    status: "Submitted",
  });

  /* ----------------------------------------------------
   * LOAD AUTHORS (ROLE FILTERED) WITH TOKEN
   ----------------------------------------------------*/
  useEffect(() => {
  axios
    .get("http://localhost:5000/api/users/authors", {
      headers: { Authorization: `Bearer ${token}` },
    })
    .then((res) => {
      setAuthors(Array.isArray(res.data) ? res.data : []);
    })
    .catch((err) => console.error("Error loading authors", err));
}, [token]);
  /* ----------------------------------------------------
   * LOAD MANUSCRIPT (EDIT MODE)
   ----------------------------------------------------*/
  useEffect(() => {
    if (method === "edit" && id) {
      api
        .get(`/${id}`, {
          headers: { Authorization: `Bearer ${token}` },
        })
        .then((res) => {
          const m = res.data;

          setForm((prev) => ({
            ...prev,
            title: m.title || "",
            abstract: m.abstract || "",
            keywords: m.keywords?.join(",") || "",
            reference_list: m.reference_list || "",
            cover_letter: m.cover_letter || "",
            plagiarism_score: m.plagiarism_score || 0,
            author_id: m.author_id || "",
            journal_id: m.journal_id || "",
            assigned_editor_id: m.assigned_editor_id || "",
            status: m.status || "Submitted",
            supplementary_materials: [],
          }));

          setLoading(false);
        })
        .catch((err) => {
          console.error("Load manuscript error:", err);
          setLoading(false);
        });
    } else {
      setLoading(false);
    }
  }, [method, id, token]);

  /* ----------------------------------------------------
   * HANDLE SUBMIT WITH TOKEN
   ----------------------------------------------------*/
  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!form.author_id) return alert("Please select an author.");
    if (!form.journal_id) return alert("Journal ID is required.");

    const fd = new FormData();

    Object.entries(form).forEach(([key, value]) => {
      if (key === "supplementary_materials") {
        Array.from(value).forEach((file) =>
          fd.append("supplementary_materials", file)
        );
      } else {
        fd.append(key, value);
      }
    });

    try {
      if (method === "create") {
        await api.post("/", fd, {
          headers: { Authorization: `Bearer ${token}` },
        });
      } else {
        await api.put(`/${id}`, fd, {
          headers: { Authorization: `Bearer ${token}` },
        });
      }

      navigate("/journal/list");
    } catch (err) {
      console.error("Submit error:", err);
      alert("Error submitting manuscript. Please check console.");
    }
  };

  if (loading) return <p>Loading...</p>;

  return (
    <div className="container mt-4">
      <h3>{method === "create" ? "Create Manuscript" : "Edit Manuscript"}</h3>

      <form onSubmit={handleSubmit} className="row g-3">
        <div className="col-12">
          <input
            className="form-control"
            placeholder="Title"
            value={form.title}
            onChange={(e) => setForm({ ...form, title: e.target.value })}
            required
          />
        </div>

        <div className="col-12">
          <textarea
            className="form-control"
            placeholder="Abstract"
            value={form.abstract}
            onChange={(e) => setForm({ ...form, abstract: e.target.value })}
            rows={4}
            required
          />
        </div>

        {/* Authors Dropdown */}
        <div className="col-md-6">
          <label className="form-label">Select Author</label>
          <select
            className="form-control"
            value={form.author_id}
            onChange={(e) => setForm({ ...form, author_id: e.target.value })}
            required
          >
            <option value="">-- Select Author --</option>
            {authors.map((a) => (
              <option key={a.id} value={a.id}>
                {a.name}
              </option>
            ))}
          </select>
        </div>

        <div className="col-12">
          <input
            className="form-control"
            placeholder="Keywords (comma separated)"
            value={form.keywords}
            onChange={(e) => setForm({ ...form, keywords: e.target.value })}
          />
        </div>

        <div className="col-12">
          <textarea
            className="form-control"
            placeholder="Reference List"
            value={form.reference_list}
            onChange={(e) => setForm({ ...form, reference_list: e.target.value })}
            rows={4}
          />
        </div>

        <div className="col-12">
          <input
            type="file"
            className="form-control"
            onChange={(e) =>
              setForm({ ...form, manuscript_file: e.target.files[0] })
            }
          />
        </div>

        <div className="col-12">
          <button className="btn btn-primary w-100">Save</button>
        </div>
      </form>
    </div>
  );
}
